import{_ as t,c as o,o as a,ag as s}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/permissions.md","filePath":"guide/permissions.md","lastUpdated":1791309864000}'),r={name:"guide/permissions.md"};function n(i,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h1><p>nPlyr is deliberately <strong>light on permissions</strong>. Because it is a media player (not a clipboard or screen tool), it does <strong>not</strong> ask for Accessibility or Screen Recording. The only permissions that may appear are the standard ones any network and file app needs.</p><h2 id="network-access" tabindex="-1">Network access <a class="header-anchor" href="#network-access" aria-label="Permalink to &quot;Network access&quot;">​</a></h2><p>Streaming, sniffing and mini-program sources all require outbound network access. On macOS this is allowed by the App Store sandbox by default — there is <strong>no prompt</strong> and nothing to grant manually.</p><h2 id="files-and-folders" tabindex="-1">Files and Folders <a class="header-anchor" href="#files-and-folders" aria-label="Permalink to &quot;Files and Folders&quot;">​</a></h2><ul><li><strong>Opening a local file</strong> uses the standard macOS open panel, so you pick the file yourself; no blanket folder access is required.</li><li><strong>Saving downloads</strong> writes to your <strong>Downloads</strong> folder (or a folder you choose). The first time you download, macOS may show a sandbox prompt to confirm the location. Grant it once and nPlyr remembers the choice.</li></ul><p>If you later move nPlyr&#39;s data or revoke access, you can re-grant it in <strong>System Settings → Privacy &amp; Security → Files and Folders</strong>.</p><h2 id="notifications-optional" tabindex="-1">Notifications (optional) <a class="header-anchor" href="#notifications-optional" aria-label="Permalink to &quot;Notifications (optional)&quot;">​</a></h2><p>nPlyr may show a local notification when a download finishes. This is optional and can be turned off in <strong>System Settings → Notifications → nPlyr</strong>.</p><h2 id="what-nplyr-does-not-request" tabindex="-1">What nPlyr does <em>not</em> request <a class="header-anchor" href="#what-nplyr-does-not-request" aria-label="Permalink to &quot;What nPlyr does *not* request&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Needed?</th><th>Why not</th></tr></thead><tbody><tr><td>Accessibility</td><td>No</td><td>Keyboard shortcuts use in-app event monitors, not global accessibility control.</td></tr><tr><td>Screen Recording</td><td>No</td><td>nPlyr plays and captures <em>network</em> media; it never records your screen.</td></tr><tr><td>Full Disk Access</td><td>No</td><td>All file access goes through the open/save panels or the Downloads folder.</td></tr><tr><td>Camera / Microphone</td><td>No</td><td>nPlyr is a viewer; it does not capture input devices.</td></tr></tbody></table><p>If you see a permission prompt that isn&#39;t listed here, it is almost certainly from a mini-program or the browser reaching a specific site — not from the core app. See <a href="/guide/troubleshooting.html">Troubleshooting</a> if something looks wrong.</p>',12)])])}const u=t(r,[["render",n]]);export{m as __pageData,u as default};
